package com.example.familymenu.family.repository;
import com.example.familymenu.family.domain.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository; import java.util.*; import java.util.concurrent.atomic.AtomicLong;
@Repository @Profile("memory") public class InMemoryFamilyRepository implements FamilyRepository { private final AtomicLong ids=new AtomicLong(); private final Map<Long,Family> families=new HashMap<>(); private final Map<Long,List<FamilyMember>> members=new HashMap<>(); private final AtomicLong mids=new AtomicLong(); public synchronized Family create(String n,String o){long uid=ids.incrementAndGet(),fid=ids.incrementAndGet(); families.put(fid,new Family(fid,n,uid)); members.put(fid,new ArrayList<FamilyMember>()); members.get(fid).add(new FamilyMember(mids.incrementAndGet(),fid,uid,o,"OWNER")); return families.get(fid);} public Optional<Family> findById(Long id){return Optional.ofNullable(families.get(id));} public List<Family> findByUserNickname(String n){List<Family>x=new ArrayList<>();for(Family f:families.values())for(FamilyMember m:findMembers(f.getId()))if(m.getNickname().equals(n)){x.add(f);break;}return x;} public List<FamilyMember> findMembers(Long id){return new ArrayList<>(members.getOrDefault(id,Collections.<FamilyMember>emptyList()));} public synchronized FamilyMember addMember(Long id,String n,String r){long uid=ids.incrementAndGet();FamilyMember m=new FamilyMember(mids.incrementAndGet(),id,uid,n,r);members.get(id).add(m);return m;} public synchronized boolean updateMemberRole(Long id,Long mid,String r){List<FamilyMember> ms=members.get(id);if(ms==null)return false;for(int i=0;i<ms.size();i++){FamilyMember m=ms.get(i);if(m.getId().equals(mid)&&!"OWNER".equals(m.getRole())){ms.set(i,new FamilyMember(m.getId(),id,m.getUserId(),m.getNickname(),r));return true;}}return false;} public synchronized boolean removeMember(Long id,Long mid){List<FamilyMember> ms=members.get(id);if(ms==null)return false;return ms.removeIf(m->m.getId().equals(mid)&&!"OWNER".equals(m.getRole()));} public synchronized boolean deleteFamily(Long id){return families.remove(id)!=null&&members.remove(id)!=null;} }
